CASE 
	WHEN "Source" = 'MATCH' THEN 
		CASE 
			WHEN is_member IS TRUE AND paid_status = 'FREE' THEN 'MEMBER'
			WHEN code IS NOT NULL THEN 'PROMOCODE'
			WHEN paid_status = 'PAID' THEN 'DAILY PAID'
			WHEN paid_status = 'FREE' THEN 'DAILY FREE MATCH'
		END
	WHEN "Source" = 'EVENT' THEN 
		CASE
			WHEN registration_price = 0 THEN 'FREE'
			WHEN registration_price <> 0 THEN 'PAID'
		END
	ELSE NULL
END AS "Type Of Payment"

FROM (

    SELECT
        'MATCH' AS "Source",
        m.registration_price,
        um.created_at AS "Date of Match Registration",
        c.name AS "City",
        f.title AS "Field",
        m.start_date::timestamp AT TIME ZONE time_zones.name AT TIME ZONE 'utc' AS "Match Start",
        m.start_date_utc::timestamp AS "Match Time",
        time_zones.name AS "Time Zone",
        m.start_date::timestamp AT TIME ZONE time_zones.name AT TIME ZONE 'utc' AS start_date_utc_converted,
        m.start_date,
        m.end_date::timestamp AT TIME ZONE time_zones.name AT TIME ZONE 'utc' AS "Match End",
        u.id AS "User ID",
        u.phone_number AS "Phone Number",
        u.first_name AS "First Name",
        u.last_name AS "Last Name",
        u.email AS "Email",
        user_city.name AS "Preferable City",
        um.paid_status,
        promocodes.code,
        promocodes.code AS "Promocode",
        m.is_cancelled AS "Match Canceled",
        um.is_cancelled,
        um.canceled_at,
        um.canceled_at AS "Canceled At",
        um.cancelled_before_24_hours,
        promocodes.discount_type,
        promocodes.discount_value,
        EXTRACT(EPOCH FROM (m.start_date_utc - um.canceled_at)) AS difference_canceled_at,
        EXISTS (
            SELECT 1
            FROM user_subscriptions
            WHERE user_id = u.id
              AND status IN ('CANCELED', 'ACTIVE')
              AND created_at < m.start_date_utc
              AND current_period_end > m.start_date_utc
            LIMIT 1
        ) AS is_member
    FROM users u
    INNER JOIN user_matches um ON u.id = um.user_id
    INNER JOIN matches m ON um.match_id = m.id
    INNER JOIN fields f ON m.field_id = f.id
    INNER JOIN cities c ON f.city_id = c.id
    INNER JOIN cities user_city ON u.preferable_city_id = user_city.id
    INNER JOIN time_zones ON c.time_zone_id = time_zones.id
    LEFT JOIN promocodes ON um.promocode_id = promocodes.id
    WHERE um.paid_status IN ('PAID', 'FREE')
      AND (
        (EXISTS (
            SELECT 1
            FROM user_subscriptions
            WHERE user_id = u.id
              AND status IN ('CANCELED', 'ACTIVE')
              AND created_at < m.start_date_utc
              AND current_period_end > m.start_date_utc
            LIMIT 1
         )
         AND um.is_cancelled IS TRUE
         AND EXTRACT(EPOCH FROM (m.start_date_utc - um.canceled_at)) < 60 * 60 * 12)
        OR
        (NOT EXISTS (
            SELECT 1
            FROM user_subscriptions
            WHERE user_id = u.id
              AND status IN ('CANCELED', 'ACTIVE')
              AND created_at < m.start_date_utc
              AND current_period_end > m.start_date_utc
            LIMIT 1
         )
         AND um.is_cancelled IS TRUE
         AND EXTRACT(EPOCH FROM (m.start_date_utc - um.canceled_at)) < 60 * 60 * 24)
        OR um.is_cancelled IS FALSE
      )

    UNION ALL

    SELECT
        'EVENT' AS "Source",
        ept.amount AS registration_price,
        ept.created_at AS "Date of Match Registration",
        c.name AS "City",
        f.title AS "Field",
		e.start_date::timestamp AT TIME ZONE tz.name AT TIME ZONE 'utc' AS "Match Start",
        e.start_date_utc::timestamp AS "Match Time",
        tz.name AS "Time Zone",
        NULL AS start_date_utc_converted,
        NULL AS start_date,
        e.end_date::timestamp AT TIME ZONE tz.name AT TIME ZONE 'utc' AS "Match End",
        u.id AS "User ID",
        u.phone_number AS "Phone Number",
        u.first_name AS "First Name",
        u.last_name AS "Last Name",
        u.email AS "Email",
        user_city.name AS "Preferable City",
        ept.paid_status,
        NULL AS code,
        NULL AS "Promocode",
        NULL AS "Match Canceled",
        ept.is_cancelled AS is_cancelled,
        ept.canceled_at AS canceled_at,
        ept.canceled_at AS "Canceled At",
        NULL AS cancelled_before_24_hours,
        NULL AS discount_type,
        NULL AS discount_value,
        NULL AS difference_canceled_at,
